steps.details:
Create `src/lib/component-map.ts` that exports a `COMPONENT_MAP` constant:
```ts
export const COMPONENT_MAP: Record<string, Record<string, React.ComponentType<any>>> = {
  hero: { centered: HeroCentered, split: HeroSplit },
  services: { grid: ServicesGrid, list: ServicesList },
  // ... all 21 section types
};
```
Import all section components.

```tsx
export function SectionRenderer({ section, business }: { section: SiteSection, business: BusinessInfo }) {
  const Component = COMPONENT_MAP[section.type]?.[section.variant];
  if (!Component) return null;
  return <Component content={section.content as any} business={business} />;
}
```

```tsx
export function SiteRenderer({ config }: { config: SiteConfig }) {
  const visibleSections = config.sections.filter(s => s.visible);
  return (
    <div>
      {visibleSections.map(section => (
        <SectionRenderer key={section.id} section={section} business={config.businessInfo} />
      ))}
    </div>
  );
}
```
